from __future__ import annotations

"""Hand out a valid access token, refreshing just before it lapses.

A request handler asks this for an access token. If the stored token is past the
refresh threshold, it refreshes against the token endpoint, stores the result,
and returns the fresh token. Callers should never receive a token that is about
to expire mid-flight.
"""

from oauth_models import TokenSet
from token_clock import Clock, DEFAULT_SKEW_SECONDS, needs_refresh
from token_endpoint import ScriptedTokenEndpoint
from token_refresher import refresh_token_set
from token_store import TokenStore


class AuthSession:
    def __init__(
        self,
        store: TokenStore,
        endpoint: ScriptedTokenEndpoint,
        clock: Clock,
        skew_seconds: int = DEFAULT_SKEW_SECONDS,
    ) -> None:
        self._store = store
        self._endpoint = endpoint
        self._clock = clock
        self._skew_seconds = skew_seconds
        self.refresh_count = 0

    def get_valid_access_token(self, user_id: str, now: int | None = None) -> str:
        """Return an access token good to use right now, refreshing if needed."""

        now = self._clock.now() if now is None else now
        token = self._store.require(user_id)

        if needs_refresh(token, now, self._skew_seconds):
            token = self._do_refresh(user_id, token, now)

        return token.access_token

    def _do_refresh(self, user_id: str, token: TokenSet, now: int) -> TokenSet:
        refreshed = refresh_token_set(token, self._endpoint, now)
        self._store.save(user_id, refreshed)
        self.refresh_count += 1
        return refreshed

    def current_token(self, user_id: str) -> TokenSet:
        return self._store.require(user_id)

    def force_refresh(self, user_id: str, now: int | None = None) -> TokenSet:
        now = self._clock.now() if now is None else now
        token = self._store.require(user_id)
        return self._do_refresh(user_id, token, now)

    def is_authenticated(self, user_id: str) -> bool:
        return self._store.has(user_id)

    def token_status(self, user_id: str, now: int | None = None) -> str:
        from token_clock import expiry_status

        now = self._clock.now() if now is None else now
        return expiry_status(self._store.require(user_id), now, self._skew_seconds)

    def ensure_fresh(self, user_id: str, now: int | None = None) -> TokenSet:
        """Refresh if needed, then return the stored (current) token set."""

        self.get_valid_access_token(user_id, now)
        return self._store.require(user_id)

    def refresh_all(self, now: int | None = None) -> int:
        """Refresh every stored user that is due, returning how many refreshed."""

        now = self._clock.now() if now is None else now
        before = self.refresh_count
        for user_id in self._store.all_user_ids():
            self.get_valid_access_token(user_id, now)
        return self.refresh_count - before

    def has_usable_refresh_token(self, user_id: str) -> bool:
        token = self._store.get(user_id)
        return bool(token and token.refresh_token)

