from __future__ import annotations

"""Token models for the Spotify Authorization Code flow.

Refreshing exchanges a refresh token for a fresh access token at the token
endpoint. The response always carries a new ``access_token`` and ``expires_in``,
but it only sometimes carries a new ``refresh_token`` — rotation is optional, and
when it is absent the existing refresh token stays valid and must be kept.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class TokenResponse:
    """A decoded response from POST /api/token."""

    access_token: str
    token_type: str
    expires_in: int
    scope: str | None = None
    refresh_token: str | None = None

    def __post_init__(self) -> None:
        if not self.access_token.strip():
            raise ValueError("access_token is required")
        if self.expires_in <= 0:
            raise ValueError("expires_in must be positive")

    def rotated_refresh_token(self) -> bool:
        return bool(self.refresh_token)

    @classmethod
    def from_raw(cls, raw: dict) -> "TokenResponse":
        return cls(
            access_token=str(raw.get("access_token", "")),
            token_type=str(raw.get("token_type", "Bearer")),
            expires_in=int(raw.get("expires_in", 3600)),
            scope=raw.get("scope"),
            refresh_token=raw.get("refresh_token"),
        )


@dataclass(frozen=True)
class TokenSet:
    """The stored credential a user session reads from."""

    access_token: str
    refresh_token: str | None
    expires_at: int
    scope: str = ""
    token_type: str = "Bearer"

    def __post_init__(self) -> None:
        if not self.access_token.strip():
            raise ValueError("access_token is required")
        if self.expires_at < 0:
            raise ValueError("expires_at must be non-negative")

    def has_refresh_token(self) -> bool:
        return bool(self.refresh_token)

    def with_updates(
        self,
        access_token: str,
        refresh_token: str | None,
        expires_at: int,
        scope: str | None = None,
    ) -> "TokenSet":
        return TokenSet(
            access_token=access_token,
            refresh_token=refresh_token,
            expires_at=expires_at,
            scope=scope if scope is not None else self.scope,
            token_type=self.token_type,
        )


def build_token_set(
    access_token: str,
    refresh_token: str,
    expires_at: int,
    scope: str = "user-library-read",
) -> TokenSet:
    return TokenSet(
        access_token=access_token,
        refresh_token=refresh_token,
        expires_at=expires_at,
        scope=scope,
    )

