from __future__ import annotations

"""Time and expiry decisions for access tokens.

Access tokens should be refreshed a little *before* they expire. Clock skew
between client and server plus the latency of an in-flight request mean a token
that looks valid for a few more seconds can still be rejected by the time the
request lands. A skew buffer absorbs that.
"""

import time


DEFAULT_SKEW_SECONDS = 60


class Clock:
    """Wall-clock source, in integer epoch seconds."""

    def now(self) -> int:
        return int(time.time())


class FixedClock(Clock):
    """Deterministic clock for tests and replay."""

    def __init__(self, fixed_now: int) -> None:
        self._now = fixed_now

    def now(self) -> int:
        return self._now

    def set(self, value: int) -> None:
        self._now = value


def seconds_until_expiry(token, now: int) -> int:
    return token.expires_at - now


def is_expired(token, now: int) -> bool:
    return now >= token.expires_at


def needs_refresh(token, now: int, skew_seconds: int = DEFAULT_SKEW_SECONDS) -> bool:
    """Whether a token should be refreshed before being used at ``now``."""

    return now >= token.expires_at


def expiry_status(token, now: int, skew_seconds: int = DEFAULT_SKEW_SECONDS) -> str:
    if is_expired(token, now):
        return "expired"
    if needs_refresh(token, now, skew_seconds):
        return "within_skew"
    return "valid"


def is_valid(token, now: int) -> bool:
    """True while the token has not yet passed its hard expiry."""

    return not is_expired(token, now)


def expires_in_seconds(token, now: int) -> int:
    """Seconds of life left, never negative."""

    return max(0, token.expires_at - now)


def describe_expiry(token, now: int) -> str:
    return (
        f"expires_at={token.expires_at} now={now} "
        f"({expires_in_seconds(token, now)}s left)"
    )


def assert_usable(token, now: int) -> None:
    """Raise if the token is already past hard expiry."""

    if is_expired(token, now):
        raise ValueError(describe_expiry(token, now))

