from __future__ import annotations

"""A scripted stand-in for Spotify's POST /api/token endpoint.

Real refreshes are nondeterministic about whether they rotate the refresh token,
so tests script the exact responses. A response without a ``refresh_token`` means
"keep using the one you already have." Presenting an empty refresh token is an
invalid grant, just like the real endpoint.
"""


class InvalidGrantError(ValueError):
    """Raised when the presented refresh token is missing or empty."""


class ScriptedTokenEndpoint:
    def __init__(self, responses: list[dict]) -> None:
        if not responses:
            raise ValueError("at least one scripted response is required")
        self._responses = list(responses)
        self._index = 0
        self.call_count = 0
        self.presented_refresh_tokens: list[str] = []

    def exchange_refresh_token(self, refresh_token: str | None) -> dict:
        if not refresh_token:
            raise InvalidGrantError("invalid_grant: refresh token missing")
        self.presented_refresh_tokens.append(refresh_token)
        response = self._responses[min(self._index, len(self._responses) - 1)]
        self._index += 1
        self.call_count += 1
        return dict(response)

    def remaining(self) -> int:
        return max(0, len(self._responses) - self._index)

    def last_presented_refresh_token(self) -> str | None:
        return self.presented_refresh_tokens[-1] if self.presented_refresh_tokens else None

    def reset(self) -> None:
        self._index = 0
        self.call_count = 0
        self.presented_refresh_tokens = []


def is_rotation_response(response: dict) -> bool:
    """True if a token-endpoint response carries a new refresh token."""

    return bool(response.get("refresh_token"))


def error_response(error: str = "invalid_grant", description: str = "") -> dict:
    return {"error": error, "error_description": description}


def non_rotating_response(access_token: str, expires_in: int = 3600) -> dict:
    """A refresh response that deliberately omits a new refresh token."""

    return access_token_response(access_token, expires_in=expires_in)


def rotating_response(access_token: str, new_refresh_token: str, expires_in: int = 3600) -> dict:
    return access_token_response(
        access_token, expires_in=expires_in, refresh_token=new_refresh_token
    )


def access_token_response(
    access_token: str,
    expires_in: int = 3600,
    scope: str = "user-library-read",
    refresh_token: str | None = None,
) -> dict:
    """Build a raw token-endpoint response, optionally rotating the refresh token."""

    response: dict = {
        "access_token": access_token,
        "token_type": "Bearer",
        "expires_in": expires_in,
        "scope": scope,
    }
    if refresh_token is not None:
        response["refresh_token"] = refresh_token
    return response

