from __future__ import annotations

"""Exchange a refresh token for a fresh TokenSet."""

from oauth_models import TokenResponse, TokenSet
from token_endpoint import ScriptedTokenEndpoint


def refresh_token_set(
    current: TokenSet,
    endpoint: ScriptedTokenEndpoint,
    now: int,
) -> TokenSet:
    """Refresh ``current`` against the token endpoint and return the new set."""

    raw = endpoint.exchange_refresh_token(current.refresh_token)
    response = TokenResponse.from_raw(raw)

    expires_at = now + response.expires_in

    return current.with_updates(
        access_token=response.access_token,
        refresh_token=response.refresh_token,
        expires_at=expires_at,
        scope=response.scope,
    )


def refresh_and_store(
    user_id: str,
    current: TokenSet,
    endpoint: ScriptedTokenEndpoint,
    store,
    now: int,
) -> TokenSet:
    """Refresh and persist the new token in one step."""

    refreshed = refresh_token_set(current, endpoint, now)
    store.save(user_id, refreshed)
    return refreshed


def describe_refresh(before: TokenSet, after: TokenSet) -> str:
    rotated = before.refresh_token != after.refresh_token
    return (
        f"access {before.access_token} -> {after.access_token}; "
        f"refresh {'rotated' if rotated else 'unchanged'}; "
        f"expires_at {after.expires_at}"
    )


from dataclasses import dataclass


@dataclass(frozen=True)
class RefreshOutcome:
    before: TokenSet
    after: TokenSet

    def rotated(self) -> bool:
        return self.before.refresh_token != self.after.refresh_token

    def kept_refresh_token(self) -> bool:
        return self.after.refresh_token == self.before.refresh_token


def refresh_with_outcome(
    current: TokenSet,
    endpoint: ScriptedTokenEndpoint,
    now: int,
) -> RefreshOutcome:
    after = refresh_token_set(current, endpoint, now)
    return RefreshOutcome(before=current, after=after)


def refresh_many(
    sets: list[TokenSet],
    endpoint: ScriptedTokenEndpoint,
    now: int,
) -> list[TokenSet]:
    return [refresh_token_set(token, endpoint, now) for token in sets]

